cd /home/daniel/ui-work/runs/202610271-as/sandbox/officehq-angular-spring; python3 - <<'EOF'
p='src/main/frontend/src/app/features/periods/periods.ts'
s=open(p).read()
anchor="// The sheet's periods, earliest first,"
add='''/** Per period id, its classic due-total: the dues as shown now of the people's claims due by a date in it that count
 * (OPEN, PENDING or SETTLED) by their status now, added up, with the same claims left out as personPeriodTotals; or once
 * closed or soft-closed the figure fixed then. */
export function classicPeriodDueTotals(periods: Period[], people: PersonWithClaims[]): Record<number, string> {
  const totals: Record<number, number> = {};
  for (const p of periods) totals[p.id] = 0;
  for (const person of people) {
    for (const c of person.claims) {
      if (c.due === null || heldOut(c, person.holds) || retiredOut(c, person.retiredNow) || c.deferred) continue;
      const period = periodOf(periods, c.dueBy);
      if (!period || isFixed(period)) continue;
      if (c.status === 'OPEN' || c.status === 'PENDING' || c.status === 'SETTLED') totals[period.id] += cents(c.due);
    }
  }
  const shown: Record<number, string> = {};
  for (const p of periods) shown[p.id] = isFixed(p) ? (p.closedTotal ?? '0.00') : (totals[p.id] / 100).toFixed(2);
  return shown;
}

'''
s=s.replace(anchor,add+anchor,1)
open(p,'w').write(s)

p='src/main/frontend/src/app/features/summary/summary.ts'
s=open(p).read()
s=s.replace("import { Period, periodDueTotals } from","import { Period, classicPeriodDueTotals, periodDueTotals } from")
s=s.replace("""// claims have it; per reason on the sheet's void reasons, how many VOID claims were voided with it.""","""// claims have it; per reason on the sheet's void reasons, how many VOID claims were voided with it. Beside it the classic
// summary: per period, its due-total counting each claim by its status now (see classicPeriodDueTotals), and the
// sheet's due-total untrimmed: everyone's due-total added up (n/a skipped).""")
s=s.replace("""    </section>
  `,""","""    </section>
    <section aria-label="Classic summary">
      <h2>Classic summary</h2>
      <table>
        <caption>By period, by status now</caption>
        <thead>
          <tr><th scope="col">Period</th><th scope="col">Due total</th></tr>
        </thead>
        <tbody>
          @for (p of classicByPeriod(); track p.name) {
            <tr>
              <th scope="row">{{ p.name }}</th>
              <td [attr.data-testid]="'classic-period-' + p.name + '-due-total'">{{ p.dueTotal }}</td>
            </tr>
          }
        </tbody>
      </table>
      <p>Due total: <span data-testid="classic-due-total">{{ classicDueTotal() }}</span></p>
    </section>
  `,""")
s=s.replace("""  protected readonly byStatus =""","""  protected readonly classicByPeriod = computed(() => {
    const totals = classicPeriodDueTotals(this.periods(), this.people());
    return this.periods().map((p) => ({ name: p.name, dueTotal: totals[p.id] }));
  });

  protected readonly classicDueTotal = computed(() => {
    const due = this.people().reduce((sum, p) => sum + (p.dueTotal === null ? 0 : cents(p.dueTotal)), 0);
    return (due / 100).toFixed(2);
  });

  protected readonly byStatus =""")
open(p,'w').write(s)
